#define sat clamp01
sampler sampler_pw_noise_lq;
vec2 uv1,uv2, rs, uvpat, grasart;
float  z, sun, tmp, gnd, fels, gras, weg, wstruc, mask, ycomp;
vec3 uvg, uvn, ret1; //Grund; Nebel
static mat2 CamRot = mat2 (q8,-q9,q9,q8);
const float fov = q6, YCam = q5, WegX = q1, WegY = q2, WegR = q3, Hell = q4, copyable = q25;
const float SysZ = q18, MaxDist = q7, RelZ = SysZ/MaxDist, RelVis = q19/MaxDist;
float noise3_lq (vec2 uvi) { float n1,n2,n3;
uvi = uvi + uTime*.001;
n1 = texture(sampler_noise_lq, (uvi)).r;
n2 = texture(sampler_noise_lq, (uvi * 2.0)).r;
n3 = texture(sampler_noise_lq, (uvi * 4.0)).r;
return n1 + n2 / 2.0 + n3 / 4.0 - .875;}
float alti (float x0, float z0)
{return q10*z0*(sin(x0*q11 + q13*z0)) * sin(z0*q12+q13) + pow(x0, 2.0 )*q14
+ 4.0 * abs(noise3_lq(.00022*vec2(x0,z0)))*RelZ ;} //sin bei z ersetzen ##!

void main() {
  vec3 ret = vec3(0.0);
  vec2 uv = vUv;
  vec2 uv_orig = vUvOriginal;
  float rad = vRadius;
  float ang = vAngle;
  ret = GetPixel(uv_orig);
mask = 1;
uv1 = (uv_orig-vec2(.5, .5)) * uAspect.xy;
uvg.z = SysZ;
uvg.x = uv1.x * uvg.z/fov;
uvg.y = alti (uvg.x, uvg.z);
uvn = uvg;
float y1 = uvg.y;
float y2 = alti (uvg.x + 4.0,uvg.z);
weg = WegX - uvg.x  + noise3_lq(uvg.xz*.0012)*WegR;
wstruc = noise3_lq(weg*0.004 + uvg.xz*0.00);
weg = clamp01(3.0 - abs(weg) - WegR / 8.0);
fels = sat(noise3_lq(.0012*uvg.xz)-.2) * 3.0*(1.0 - weg); //Fels nicht hoeher als YCam !
gras = sat(1.0 - fels)*sat(1.0 - weg) * sat(2+4*noise3_lq(uvg.xz*.0003));;
grasart = 0.25*ceil(4.0 * texture(sampler_noise_lq, uvg.xz*0.000723+q10).xy);
uvpat = uv*mix(vec2( 2.0 , 1.0)*texture(sampler_noise_lq,uvg.xz*0.0063).xz,
vec2( 32.0 , 8.0 )*grasart.xy,
clamp01(2.0 * gras - 2.0*weg));
float pat0 = sat(texture(sampler_noise_lq,uvpat*RelZ+rand_frame).g +wstruc*weg) ;;
float pat = mix(pat0, .0, clamp01(fels * 2.0));
uvg.y += fels + (pat-0.5)* gras*1.3 ;
uvg.y = mix(uvg.y-weg / 2.0,WegY-wstruc / 2.0,weg*0.7);
//PROJEKTION
uvg.yz = multiply(uvg.yz,CamRot);
rs     = fov/uvg.z * vec2 (uvg.x,uvg.y - YCam);
gnd = clamp01((4*512*RelZ*pow(rs.y+uv1.y, 1.0 ))) ;
ret1 = vec3 (mix(0.65*sat(.7+grasart.y-gras),0.9-wstruc,weg), (0.3*gnd*pat+weg / 16.0)*Hell*(1+0*(y2-y1)), RelVis-RelZ);
//ret1.g *= 0.2+0.8*sat(GetBlur2(uv_orig).g); //hm !!!!!!!!!!!!!!
ret = mix(ret, ret1, gnd*mask);
//BodenNebel
uvn.yz = multiply(uvn.yz,CamRot);
rs     = fov/uvn.z * vec2 (uvn.x,uvn.y - YCam + 0.0); //Nebelhoehe noch definieren ####
float noise = texture(sampler_noise_hq,uvn.xz*0.005).r ;
gnd = clamp01((1-4000*RelZ*rand_frame.x*pow(rs.y+uv1.y, 2.0 )))*0.07*noise;
ret.b = mix(ret.b, 0.0 , gnd*mask);
uv2.x = 1.0 - abs( fract((uv2.x-.5) * 0.5 ) * vec2(1.8,1.4) - 1.0 ); // Eo.S. mirror code
uv2 = (uv_orig - 0.5)*vec2( 2.0 ,1.8)+vec2 (0.5+1.25*(rand_frame.x-0.5), 0.7);
uv2.y += -.5*pow(uv2.x-0.5, 2.0 );
vec3 copy = GetPixel(uv2);
float cmask = sat (1.0 - pow(2.0 * max(abs(uv2.x-0.5), abs(uv2.y-0.5)), 2.0 ))*0.46*q25;
if (q30) {ret =  mix(vec3( 1.0 , 1.0 , 0.0),copy,vec3( 0.0 ,cmask,cmask)) ;};
//ret = cmask / 3.0;
  fragColor = vec4(ret, 1.0);
}

